def most_common_char(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1

    if not counts:  # Handle empty string case
        return None

    best_char = ''
    best_count = -1

    for ch, count in counts.items():
        if count > best_count:
            best_count = count
            best_char = ch
        elif count == best_count:
            # If counts are equal, choose the character that appears earlier in the alphabet
            if best_char == '' or ch < best_char:
                best_char = ch

    return best_char
```

