def most_common_char(s):
    if not s:
        raise ValueError("Input string cannot be empty")

    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1

    best_char = ''
    best_count = -1

    for ch, count in counts.items():
        if count > best_count:
            best_count = count
            best_char = ch
        elif count == best_count:
            if best_char == '' or ch < best_char:
                best_char = ch

